// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListStreams List streams with their status
	// (GET /api/streams)
	ListStreams(ctx context.Context, request ListStreamsRequestObject) (ListStreamsResponseObject, error)
	// CreateStream Create a stream in state stopped
	// (POST /api/streams)
	CreateStream(ctx context.Context, request CreateStreamRequestObject) (CreateStreamResponseObject, error)
	// DeleteStream Remove a stream that is not running, and its breaks
	// (DELETE /api/streams/{id})
	DeleteStream(ctx context.Context, request DeleteStreamRequestObject) (DeleteStreamResponseObject, error)
	// GetStream One stream
	// (GET /api/streams/{id})
	GetStream(ctx context.Context, request GetStreamRequestObject) (GetStreamResponseObject, error)
	// ReplaceStream Replace name and spec; the spec applies on next start, the window at once
	// (PUT /api/streams/{id})
	ReplaceStream(ctx context.Context, request ReplaceStreamRequestObject) (ReplaceStreamResponseObject, error)
	// ListBreaks Upcoming, active and recent breaks of the current epoch
	// (GET /api/streams/{id}/breaks)
	ListBreaks(ctx context.Context, request ListBreaksRequestObject) (ListBreaksResponseObject, error)
	// CreateBreak Schedule a break, snapped to segment boundaries
	// (POST /api/streams/{id}/breaks)
	CreateBreak(ctx context.Context, request CreateBreakRequestObject) (CreateBreakResponseObject, error)
	// DeleteBreak Cancel a break that has not started, or end an active one early
	// (DELETE /api/streams/{id}/breaks/{breakId})
	DeleteBreak(ctx context.Context, request DeleteBreakRequestObject) (DeleteBreakResponseObject, error)
	// GetBreak One break, with its cues
	// (GET /api/streams/{id}/breaks/{breakId})
	GetBreak(ctx context.Context, request GetBreakRequestObject) (GetBreakResponseObject, error)
	// StartStream Start a new epoch from a snapshot of the spec
	// (POST /api/streams/{id}/start)
	StartStream(ctx context.Context, request StartStreamRequestObject) (StartStreamResponseObject, error)
	// GetStreamStatus Live position of the current epoch
	// (GET /api/streams/{id}/status)
	GetStreamStatus(ctx context.Context, request GetStreamStatusRequestObject) (GetStreamStatusResponseObject, error)
	// StopStream End the epoch at the frozen horizon
	// (POST /api/streams/{id}/stop)
	StopStream(ctx context.Context, request StopStreamRequestObject) (StopStreamResponseObject, error)
	// GetTime Server UTC time for DASH UTCTiming (urn:mpeg:dash:utc:http-iso:2014)
	// (GET /api/time)
	GetTime(ctx context.Context, request GetTimeRequestObject) (GetTimeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

